	"desk.menu.does.client": {args: {games: "string"}, text: "Whether a match runs, asked of {games} on this computer only."},
	"desk.menu.does.crash": "A crash report, to questpump.com, after QuestPump crashed: by itself while Send crash reports is on, else only when you press Send.",
	"desk.menu.does.data": "Its own folder",
	"desk.menu.does.detect": "Which programs run, to notice the games you play: those in Steam's game folders and the apps marked as games. A found game's name and its program are kept on this computer.",
	"desk.menu.does.detect.windows": "Which programs run, to notice the games you play: those Steam lists as its games, Windows' list of games, and the games Epic, Battle.net, Ubisoft Connect and GOG installed. A found game's name and its program are kept on this computer.",
	"desk.menu.does.drops": "From a game it takes only that a match began or ended. Your name, your score and the match itself are never kept.",
	"desk.menu.does.feedback": "Your feedback, to questpump.com, only when you press Send.",
	"desk.menu.does.file": "A file a game reads to report its matches",
	"desk.menu.does.file.shared": "A file a game shares with other apps, where QuestPump added its part. It stays when you turn the game off.",
	"desk.menu.does.game": "The game's window: QuestPump reads only the small squares the addon shows in its corner.",
	"desk.menu.does.games": {args: {games: "string"}, text: "The games QuestPump watches, to know when a match ends: {games}."},
	"desk.menu.does.games.none": "No game yet.",
	"desk.menu.does.gsi": {args: {port: "string"}, text: "News of your games' matches, from this computer only (port {port})."},
	"desk.menu.does.idle": "How long since your last key, click or touch, never which one, to know how long you sat.",
	"desk.menu.does.keeps": "What it keeps",
	"desk.menu.does.lan": {args: {port: "string"}, text: "Your paired phone and watch, on your home network (port {port}). Each message is sealed with your pairing code."},
	"desk.menu.does.listens": "What it listens to",
	"desk.menu.does.logs": {args: {games: "string"}, text: "The logs {games} write on this computer: QuestPump looks through them only for the lines that say a match began or ended, and keeps none of it."},
	"desk.menu.does.mirror": "Your progress for the game",
	"desk.menu.does.never": "It never sends a key or a click to a game and never reads or changes its memory. A game's live data is read only where the game publishes it for other apps.",
	"desk.menu.does.nothing": "Nothing else leaves this computer: no account, no tracking and no ads.",
	"desk.menu.does.removes": "Turning a game off removes its file. Uninstalling QuestPump leaves its own folder with your progress: delete that folder to remove it too.",
	"desk.menu.does.saves": {args: {games: "string"}, text: "The files {games} save on this computer: QuestPump only notices when one is saved or removed, never opens it and keeps none of it."},
	"desk.menu.does.screen": {args: {games: "string"}, text: "The middle of the window {games} show on this computer, about four times a second while they run, to see when a boss falls: QuestPump keeps no picture and no word of it."},
	"desk.menu.does.sends": "What it sends",
	"desk.menu.does.shared": {args: {games: "string"}, text: "The live data {games} publish on this computer for other apps, for when a race or a match is over."},
	"desk.menu.does.steam": {args: {games: "string"}, text: "Which programs run from the Steam folders of {games}, to know when each one closes, while Notice games I play is off."},
	"desk.menu.does.steam.windows": {args: {games: "string"}, text: "Steam's own list of the games it runs, for {games}, to know when each one closes, while Notice games I play is off."},
	"desk.menu.does.title": "What it does",
	"desk.menu.does.udp": {args: {games: "string"}, text: "The telemetry {games} send to this computer only, for when a race is over."},
	"desk.menu.does.updates": "A look for updates and the move animations, from GitHub.",
	"desk.menu.does.usage": "Counts of each day, to questpump.com, while Usage statistics is on: which features you used and how many pumps you did, without your name or any id.",
	"desk.menu.does.watches": "What it watches",
	"desk.menu.email.computer": "computer",
	"desk.menu.heart.computer": {args: {after: "int"}, text: "QuestPump on this computer does three more things. It measures every move of a pump from your heart rate before the pump's first move. With a watch, it judges moves where your hands hold you up, like push-ups, on the {after} seconds after the set, since the watch reads poorly during them. And it learns how your heart rate moves while you just play, so after a while it may ask for less or more rise, to fit your heart."},
	"desk.menu.heart.reads.line": "Only your heart rate. It comes from your watch while you run a play session on it, or from a heart-rate strap you turn on under Devices.",
	"desk.menu.heart.stays.line": "Your heart rate stays on your own devices: this computer, the game on it, your phone and your watch. It moves only between them, sealed on the way. Pluxia GmbH never gets it, and the backup file and feedback you send leave it out.",
