/** The words of `key`, its placeholders filled from `args` ({name: value}). */
export function t(key, args = {}) {
	if (!Object.hasOwn(STRINGS, key)) throw new Error(`copy: no key ${key}`);
	const entry = STRINGS[key];
	if (typeof entry === "string") return entry;
	const values = {};
	for (const [name, kind] of Object.entries(entry.args)) {
		const value = args[name];
		if (kind === "int") {
			if (!Number.isInteger(value)) throw new TypeError(`copy: ${key} takes an int ${name}`);
			values[name] = NUMBER.format(value);
		} else if (typeof value === "string") {
			values[name] = value;
		} else {
			throw new TypeError(`copy: ${key} takes a string ${name}`);
		}
	}
	const text = entry.count === undefined ? entry.text : entry[PLURAL.select(args[entry.count])];
	return text.replace(PLACEHOLDER, (_, name) => values[name]);
}
